fn render_import_statement(node: &ImportStatementTransport, w: &mut dyn ::sittir_core::render::RenderSink) -> ::sittir_core::render::RenderResult {
    let from_clause = &node.from_clause;
    let import_attribute = View::new(&node.import_attribute, "{}");
    let import_clause = View::new(&node.import_clause, "{}");
    let terminator = &node.terminator;
    w.site(node.import_statement_before.unwrap_or(0));
    w.site(node.anon_import_before.unwrap_or(0));
    w.text("import")?;
    w.site(node.anon_import_after.unwrap_or(0));
    import_clause.render(w)?;
    from_clause.render(w)?;
    import_attribute.render(w)?;
    terminator.render(w)?;
    w.site(node.import_statement_after.unwrap_or(0));
    Ok(())
}

