fn render_variable_declarator_plain(node: &VariableDeclaratorPlainTransport, w: &mut dyn ::sittir_core::render::RenderSink) -> ::sittir_core::render::RenderResult {
    let name = &node.name;
    let type_ = View::new(&node.type_, "{}");
    let value = View::new(&node.value, "{}");
    w.site(node.variable_declarator_plain_before.unwrap_or(0));
    name.render(w)?;
    type_.render(w)?;
    if value.is_present() {
        w.site(node.eq_before.unwrap_or(0));
        w.text("=")?;
        w.site(node.eq_after.unwrap_or(0));
        value.render(w)?;
    }
    w.site(node.variable_declarator_plain_after.unwrap_or(0));
    Ok(())
}

